int nthFibonacciUtil(int n, vector<int>& dp) {

    // Base case
    if (n <= 1) {
        return n;
    }

    // Check if the result is
    // already in the dp table
    if (dp[n] != -1) {
        return dp[n];
    }

    // calculate Fibonacci number
    // and store it in dp table
    dp[n] = nthFibonacciUtil(n - 1, dp) 
          + nthFibonacciUtil(n - 2, dp);

    return dp[n];
}

