int nthFibonacci(int n){

    // base cases
    if (n <= 1)
        return n;

    vector<int> dp(n + 1);
    dp[0] = 0; dp[1] = 1;

    // solving the smaller problems first
    // and finally solving the complete problem
    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
